-- Generated by OpenAI Codex on 2026-11-03. Database-owned map and preserved OSM topology.
BEGIN;
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE TABLE IF NOT EXISTS map_dataset (
    singleton BOOLEAN PRIMARY KEY DEFAULT TRUE CHECK (singleton),
    revision BIGINT NOT NULL DEFAULT 0,
    source_sha256 TEXT,
    imported_at TIMESTAMPTZ
);
INSERT INTO map_dataset(singleton) VALUES (TRUE) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS map_features (
    id TEXT PRIMARY KEY,
    object_type TEXT NOT NULL CHECK (object_type IN ('node','way','relation')),
    osm_id BIGINT,
    tags JSONB NOT NULL DEFAULT '{}',
    source_tags JSONB NOT NULL DEFAULT '{}',
    position JSONB,
    geom geometry(Geometry,4326),
    building_id TEXT REFERENCES map_features(id) DEFERRABLE INITIALLY DEFERRED,
    link_status TEXT NOT NULL DEFAULT 'not_applicable',
    geometry_status TEXT NOT NULL DEFAULT 'ok',
    version BIGINT NOT NULL DEFAULT 1,
    UNIQUE(object_type,osm_id)
);
CREATE INDEX IF NOT EXISTS map_features_geom_idx ON map_features USING GIST(geom);
CREATE INDEX IF NOT EXISTS map_features_tags_idx ON map_features USING GIN(tags);
CREATE INDEX IF NOT EXISTS map_features_building_idx ON map_features(building_id);
CREATE TABLE IF NOT EXISTS map_refs (
    feature_id TEXT NOT NULL REFERENCES map_features(id) ON DELETE CASCADE,
    ordinal INTEGER NOT NULL,
    target_key TEXT NOT NULL,
    target_id TEXT REFERENCES map_features(id) DEFERRABLE INITIALLY DEFERRED,
    member_type TEXT NOT NULL CHECK(member_type IN ('node','way','relation')),
    role TEXT NOT NULL DEFAULT '',
    PRIMARY KEY(feature_id,ordinal)
);
CREATE INDEX IF NOT EXISTS map_refs_target_idx ON map_refs(target_id);
CREATE TABLE IF NOT EXISTS map_names (
    feature_id TEXT NOT NULL REFERENCES map_features(id) ON DELETE CASCADE,
    kind TEXT NOT NULL,
    name TEXT NOT NULL,
    PRIMARY KEY(feature_id,kind,name)
);
CREATE INDEX IF NOT EXISTS map_names_search_idx ON map_names USING GIN(name gin_trgm_ops);
CREATE TABLE IF NOT EXISTS map_changes (
    id BIGSERIAL PRIMARY KEY,
    revision BIGINT NOT NULL UNIQUE,
    actor_sub TEXT NOT NULL,
    actor_email TEXT NOT NULL,
    changed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    before_state JSONB NOT NULL,
    after_state JSONB NOT NULL
);
GRANT SELECT,INSERT,UPDATE,DELETE ON map_features,map_refs,map_names TO cats;
GRANT SELECT,UPDATE ON map_dataset TO cats;
GRANT SELECT,INSERT ON map_changes TO cats;
REVOKE UPDATE,DELETE ON map_changes FROM cats;
GRANT USAGE,SELECT ON SEQUENCE map_changes_id_seq TO cats;
COMMIT;
